}

/// <summary>Styles for <see cref="TextCtrl"/>.</summary>
[Flags]
public enum TextCtrlStyle : long {
	/// <summary>No styles. Wraps 0.</summary>
	None = 0x0,
	/// <summary>The control will generate the event wxEVT_TEXT_ENTER that can be handled by the program. Otherwise, i.e. either if this style not specified at all, or it is used, but there is no event handler for this event or the event handler called wxEvent::Skip() to avoid overriding the default handling, pressing Enter key is either processed internally by the control or used to activate the default button of the dialog, if any. Wraps wxTE_PROCESS_ENTER.</summary>
	ProcessEnter = 0x400,
	/// <summary>Normally, TAB key is used for keyboard navigation and pressing it in a control switches focus to the next one. With this style, this won't happen and if the TAB is not otherwise processed (e.g. by wxEVT_CHAR event handler), a literal TAB character is inserted into the control. Notice that this style has no effect for single-line text controls when using wxGTK. Wraps wxTE_PROCESS_TAB.</summary>
	ProcessTab = 0x40,
	/// <summary>The text control allows multiple lines. If this style is not specified, line break characters should not be used in the controls value. Wraps wxTE_MULTILINE.</summary>
	MultiLine = 0x20,
	/// <summary>The text will be echoed as asterisks. Wraps wxTE_PASSWORD.</summary>
	Password = 0x800,
	/// <summary>The text will not be user-editable. Wraps wxTE_READONLY.</summary>
	ReadOnly = 0x10,
	/// <summary>Use rich text control under MSW, this allows having more than 64KB of text in the control. This style is ignored under other platforms and it is recommended to use wxTE_RICH2 instead of it under MSW. Wraps wxTE_RICH.</summary>
	Rich = 0x80,
	/// <summary>Use rich text control version 2.0 or higher under MSW, this style is ignored under other platforms. Note that this style may be turned on automatically even if it is not used explicitly when creating a text control with a long (i.e. much more than 64KiB) initial text, as creating the control would simply fail in this case under MSW if neither this style nor wxTE_RICH is used. Wraps wxTE_RICH2.</summary>
	Rich2 = 0x8000,
	/// <summary>Highlight the URLs and generate the wxTextUrlEvents when mouse events occur over them. Wraps wxTE_AUTO_URL.</summary>
	AutoUrl = 0x1000,
	/// <summary>By default, the Windows text control doesn't show the selection when it doesn't have focus - use this style to force it to always show it. It doesn't do anything under other platforms. Wraps wxTE_NOHIDESEL.</summary>
	NoHideSelection = 0x2000,
	/// <summary>A horizontal scrollbar will be created and used, so that text won't be wrapped. Wraps wxHSCROLL.</summary>
	Hscroll = 0x40000000,
	/// <summary>For multiline controls only: vertical scrollbar will never be created. This limits the amount of text which can be entered into the control to what can be displayed in it under wxMSW but not under wxGTK or wxOSX. Currently not implemented for the other platforms. Wraps wxTE_NO_VSCROLL.</summary>
	NoVscroll = 0x2,
	/// <summary>The text in the control will be left-justified (default). Wraps wxTE_LEFT.</summary>
	Left = 0x0,
	/// <summary>The text in the control will be centered (wxMSW, wxGTK, wxOSX). Wraps wxTE_CENTRE.</summary>
	Center = 0x100,
	/// <summary>The text in the control will be right-justified (wxMSW, wxGTK, wxOSX). Wraps wxTE_RIGHT.</summary>
	Right = 0x200,
	/// <summary>Same as wxHSCROLL style: don't wrap at all, show horizontal scrollbar instead. Wraps wxTE_DONTWRAP.</summary>
	DontWrap = 0x40000000,
	/// <summary>For multiline controls only: wrap the lines too long to be shown entirely at any position (wxUniv, wxGTK, wxOSX). Wraps wxTE_CHARWRAP.</summary>
	CharWrap = 0x4000,
	/// <summary>For multiline controls only: wrap the lines too long to be shown entirely at word boundaries (wxUniv, wxMSW, wxGTK, wxOSX). Wraps wxTE_WORDWRAP.</summary>
	WordWrap = 0x1,
	/// <summary>For multiline controls only: wrap the lines at word boundaries or at any other character if there are words longer than the window width (this is the default). Wraps wxTE_BESTWRAP.</summary>
	BestWrap = 0x0,
}

/// <summary>Styles for <see cref="Window"/>.</summary>
[Flags]
public enum WindowStyle : long {
	/// <summary>No styles. Wraps 0.</summary>
	None = 0x0,
	/// <summary>The window class will decide the kind of border to show, if any. Wraps wxBORDER_DEFAULT.</summary>
	BorderDefault = 0x0,
	/// <summary>Displays a thin border around the window. wxSIMPLE_BORDER is the old name for this style. Wraps wxBORDER_SIMPLE.</summary>
	BorderSimple = 0x2000000,
	/// <summary>Displays a sunken border. wxSUNKEN_BORDER is the old name for this style. Wraps wxBORDER_SUNKEN.</summary>
	BorderSunken = 0x8000000,
	/// <summary>Displays a raised border. wxRAISED_BORDER is the old name for this style. Wraps wxBORDER_RAISED.</summary>
	BorderRaised = 0x4000000,
	/// <summary>Displays a border suitable for a static control. wxSTATIC_BORDER is the old name for this style. Windows only. Wraps wxBORDER_STATIC.</summary>
	BorderStatic = 0x1000000,
	/// <summary>Displays a native border suitable for a control, on the current platform. On Windows, this will be a themed border; on most other platforms a sunken border will be used. For more information for themed borders on Windows, please see Themed borders on Windows. Wraps wxBORDER_THEME.</summary>
	BorderTheme = 0x10000000,
	/// <summary>Displays no border, overriding the default border style for the window. wxNO_BORDER is the old name for this style. Wraps wxBORDER_NONE.</summary>
	BorderNone = 0x200000,
	/// <summary>This style is obsolete and should not be used. Wraps wxBORDER_DOUBLE.</summary>
	BorderDouble = 0x10000000,
	/// <summary>This style is obsolete and doesn't do anything. See wxWindow::SetTransparent(). Wraps wxTRANSPARENT_WINDOW.</summary>
	TransparentWindow = 0x0,
	/// <summary>This style is used by wxWidgets for the windows supporting TAB navigation among their children, such as wxDialog and wxPanel. It should almost never be used in the application code. Wraps wxTAB_TRAVERSAL.</summary>
	TabTraversal = 0x80000,
	/// <summary>Use this to indicate that the window wants to get all char/key events for all keys - even for keys like TAB or ENTER which are usually used for dialog navigation and which wouldn't be generated without this style. If you need to use this style in order to get the arrows or etc., but would still like to have normal keyboard navigation take place, you should call Navigate in response to the key events for Tab and Shift-Tab. Wraps wxWANTS_CHARS.</summary>
	WantsChars = 0x40000,
	/// <summary>On Windows, this style used to disable repainting the window completely when its size is changed. Since this behaviour is now the default, the style is now obsolete and no longer has an effect. Wraps wxNO_FULL_REPAINT_ON_RESIZE.</summary>
	NoFullRepaintOnResize = 0x0,
	/// <summary>Use this style to enable a vertical scrollbar. Notice that this style cannot be used with native controls which don't support scrollbars nor with top-level windows in most ports. Wraps wxVSCROLL.</summary>
	Vscroll = 0x80000000,
	/// <summary>Use this style to enable a horizontal scrollbar. The same limitations as for wxVSCROLL apply to this style. Wraps wxHSCROLL.</summary>
	Hscroll = 0x40000000,
	/// <summary>If a window has scrollbars, disable them instead of hiding them when they are not needed (i.e. when the size of the window is big enough to not require the scrollbars to navigate it). This style is currently implemented for wxMSW, wxGTK and wxUniversal and does nothing on the other platforms. Wraps wxALWAYS_SHOW_SB.</summary>
	AlwaysShowSb = 0x800000,
	/// <summary>Use this style to eliminate flicker caused by the background being repainted, then children being painted over them. Windows only. Wraps wxCLIP_CHILDREN.</summary>
	ClipChildren = 0x400000,
	/// <summary>Use this style to force a complete redraw of the window whenever it is resized instead of redrawing just the part of the window affected by resizing. Note that this was the behaviour by default before 2.5.1 release and that if you experience redraw problems with code which previously used to work you may want to try this. Currently this style applies on GTK+ 2 and Windows only, and full repainting is always done on other platforms. Wraps wxFULL_REPAINT_ON_RESIZE.</summary>
	FullRepaintOnResize = 0x10000,
}
